#!/usr/bin/env node
/**
 * Builds the node knowledge index the assistant uses so it never invents a
 * parameter name.
 *
 * Source of truth is the `node-definitions` tree that n8n itself ships inside
 * the npm packages. It is generated by n8n's own build, so it cannot drift from
 * the real nodes the way scraped docs or hand-written notes do. Two artefacts
 * come out of it:
 *
 *   vendor/catalog.json   every node, every resource/operation, and the exact
 *                         parameter names for each. Small enough to commit and
 *                         to hold in memory. This is what `search_nodes` reads
 *                         and what the validator checks unknown keys against.
 *
 *   vendor/schemas/       the per-operation TypeScript definitions (.ts) and
 *                         n8n's own Zod validators (.schema.js), laid out the
 *                         way @n8n/workflow-sdk's setSchemaBaseDirs() expects.
 *                         `get_node_schema` serves the .ts text to the model;
 *                         validate_workflow runs the .schema.js factories.
 *
 * Only the newest version of each node is kept. Older versions exist so old
 * workflows keep working; we are always authoring new ones, and keeping all of
 * them roughly triples the size for nodes like Slack (6 versions shipped).
 *
 * Usage (never `npx` — batch shims are blocked by group policy on the target
 * machine, so everything is invoked as a plain node script):
 *
 *   node scripts/build-node-index.mjs
 *   node scripts/build-node-index.mjs --src /path/to/node_modules
 *   node scripts/build-node-index.mjs --catalog-only
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');

const args = process.argv.slice(2);
const flag = (name, fallback = null) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 ? (args[i + 1] ?? true) : fallback;
};
const CATALOG_ONLY = args.includes('--catalog-only');
const SRC = path.resolve(flag('src', path.join(ROOT, 'node_modules')));
const OUT = path.resolve(flag('out', path.join(ROOT, 'vendor')));

/** Packages that ship a node-definitions tree, in the order we search them. */
const PACKAGES = [
  { npm: 'n8n-nodes-base', defs: 'dist/node-definitions/nodes' },
  { npm: '@n8n/n8n-nodes-langchain', defs: 'dist/node-definitions/nodes' },
];

// ---------------------------------------------------------------------------
// helpers

const exists = (p) => fs.existsSync(p);
const readIf = (p) => (exists(p) ? fs.readFileSync(p, 'utf8') : null);

function readJson(p, fallback = null) {
  const raw = readIf(p);
  if (raw === null) return fallback;
  try {
    return JSON.parse(raw);
  } catch {
    return fallback;
  }
}

function rmrf(p) {
  // Only ever used on our own generated output directory, never on user data.
  if (exists(p)) fs.rmSync(p, { recursive: true, force: true });
}

function copyFileEnsuring(from, to) {
  fs.mkdirSync(path.dirname(to), { recursive: true });
  fs.copyFileSync(from, to);
}

/**
 * Version directories are named v1, v2, v21, v24 … meaning 1, 2, 2.1, 2.4.
 * A plain lexical sort puts v2 after v24, and numeric-aware sort puts v24
 * (read as twenty-four) above v3 — both wrong. Decode the n8n convention
 * instead: first digit is the major, the rest are the minor.
 */
function decodeVersionDir(name) {
  const digits = name.replace(/^v/, '');
  if (!/^\d+$/.test(digits)) return null;
  if (digits.length === 1) return Number(digits);
  return Number(`${digits[0]}.${digits.slice(1)}`);
}

function pickLatestVersionDir(dir) {
  const entries = fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isDirectory() && /^v\d+$/.test(e.name))
    .map((e) => ({ name: e.name, version: decodeVersionDir(e.name) }))
    .filter((e) => e.version !== null)
    .sort((a, b) => a.version - b.version);
  return entries.length ? entries[entries.length - 1] : null;
}

// ---------------------------------------------------------------------------
// .ts parsing
//
// The generated .ts files are machine-written with a stable shape, so a small
// parser is reliable here in a way that parsing hand-written TypeScript would
// not be. We take: the parameter names of the operation's params type, which
// of them are required, the credential types the node accepts, and the short
// human description for search.

/**
 * Extracts the params type body. n8n emits two shapes and they are not
 * interchangeable: nodes with resource/operation discriminators get
 * `export type XParams = { ... }`, while single-surface nodes get
 * `export interface XParams { ... }`. Matching only the first shape silently
 * dropped 188 of 420 nodes — including Aggregate and every Trigger — and the
 * catalog looked perfectly healthy while doing it.
 */
function extractParamsTypeBody(ts) {
  const start = ts.search(/export (?:type \w+Params\s*=\s*\{|interface \w+Params\s*\{)/);
  if (start < 0) return null;
  const open = ts.indexOf('{', start);
  let depth = 0;
  for (let i = open; i < ts.length; i++) {
    if (ts[i] === '{') depth++;
    else if (ts[i] === '}') {
      depth--;
      if (depth === 0) return ts.slice(open + 1, i);
    }
  }
  return null;
}

/**
 * Top-level parameter names live at one indent level inside the params type.
 * Nested object shapes are indented further and are not separate parameters,
 * so depth tracking matters — a naive regex over every line would report
 * `mode`, `value` and `cachedResultName` from a resource-locator as if they
 * were node parameters, and the validator would then accept garbage.
 */
function parseTopLevelParams(body) {
  const params = [];
  let depth = 0;
  for (const rawLine of body.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('*') || line.startsWith('/')) {
      // still need brace accounting for JSDoc-free lines only
    } else {
      if (depth === 0) {
        const m = line.match(/^(\w+)(\??):/);
        if (m) params.push({ name: m[1], required: m[2] !== '?' });
      }
      depth += (line.match(/\{/g) || []).length;
      depth -= (line.match(/\}/g) || []).length;
      if (depth < 0) depth = 0;
    }
  }
  return params;
}

function parseCredentials(ts) {
  const m = ts.match(/interface Credentials \{([\s\S]*?)\}/);
  if (!m) return [];
  return [...m[1].matchAll(/^\s*(\w+)\??:/gm)].map((x) => x[1]);
}

/**
 * The header comment carries the node display name, its version, and — for
 * single-surface nodes — a one-line description that is the best search text
 * we have for that node.
 */
function parseHeader(ts) {
  const m = ts.match(/^\/\*\*\s*\n\s*\*\s*(.+?)\s*-\s*Version\s*([\d.]+)\s*\n\s*\*\s*(.*)/);
  if (!m) return {};
  const third = (m[3] || '').trim();
  return {
    displayName: m[1].replace(/\s+Node$/, ''),
    version: m[2],
    // Third line is either a Discriminator marker or a human description.
    description: third.startsWith('Discriminator:') || third === '/' ? null : third.replace(/\*\/$/, '').trim() || null,
  };
}

/** Discriminator line: `Discriminator: resource=message, operation=post` */
function parseDiscriminators(ts) {
  const m = ts.match(/Discriminator:\s*(.+)/);
  if (!m) return {};
  const out = {};
  for (const pair of m[1].split(',')) {
    const [k, v] = pair.split('=').map((s) => s && s.trim());
    if (k && v) out[k] = v;
  }
  return out;
}

/**
 * Picker parameters are the ones we must never guess a value for.
 *
 * There are two distinct markers and catching only the first one is a trap:
 * n8n annotates dropdown params with @searchListMethod / @loadOptionsMethod,
 * but the *resource locator* controls — Slack's channel, Google Sheets' tab,
 * the ones a human picks from a list — carry no annotation at all. They are
 * identified only by their `{ __rl: true; mode: 'list' | 'id' | ... }` shape.
 * Slack `message:post` has zero annotated params and one resource locator, so
 * an annotation-only detector reports "nothing to ground here" on the exact
 * case this whole mechanism exists for.
 */
function parseGroundedParams(ts) {
  const out = [];
  const seen = new Set();

  // JSDoc block immediately preceding a parameter declaration.
  const blocks = ts.split('/**');
  for (const block of blocks.slice(1)) {
    const decl = block.match(/\*\/\s*\n\s*(\w+)\??:/);
    if (!decl) continue;
    const param = decl[1];
    const ann = block.match(/@(searchListMethod|loadOptionsMethod)\s+(\w+)/);
    if (ann && !seen.has(param)) {
      seen.add(param);
      out.push({
        param,
        methodType: ann[1] === 'searchListMethod' ? 'searchList' : 'loadOptions',
        method: ann[2],
      });
    }
  }

  // Resource locators, annotated or not.
  for (const m of ts.matchAll(/(\w+)\??:\s*\{\s*__rl:\s*true;\s*mode:\s*([^;]+);/g)) {
    const param = m[1];
    if (seen.has(param)) continue;
    seen.add(param);
    out.push({
      param,
      methodType: 'resourceLocator',
      modes: [...m[2].matchAll(/'([^']+)'/g)].map((x) => x[1]),
    });
  }

  return out;
}

// ---------------------------------------------------------------------------
// walk

function collectOperationFiles(versionDir) {
  /** @type {{resource:string|null, file:string}[]} */
  const files = [];
  const walk = (dir, resource) => {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, e.name);
      if (e.isDirectory() && e.name.startsWith('resource_')) {
        walk(p, e.name.slice('resource_'.length));
      } else if (e.isFile() && e.name.endsWith('.ts') && e.name !== 'index.ts') {
        files.push({ resource, file: p });
      }
    }
  };
  walk(versionDir, null);
  // Nodes with no resource split keep their whole surface in index.ts.
  if (!files.length && exists(path.join(versionDir, 'index.ts'))) {
    files.push({ resource: null, file: path.join(versionDir, 'index.ts') });
  }
  return files;
}

function buildNode({ pkgName, nodeDir, nodeName }) {
  const latest = pickLatestVersionDir(nodeDir);
  let versionDir = nodeDir;
  let version = null;
  let versionDirName = null;

  if (latest) {
    versionDir = path.join(nodeDir, latest.name);
    version = latest.version;
    versionDirName = latest.name;
  }

  const opFiles = collectOperationFiles(versionDir);
  if (!opFiles.length) return null;

  const nodeType = `${pkgName === 'n8n-nodes-langchain' ? '@n8n/' : ''}${pkgName}.${nodeName}`;
  const operations = [];
  let displayName = null;
  let description = null;
  let credentials = new Set();

  for (const { resource, file } of opFiles) {
    const ts = fs.readFileSync(file, 'utf8');
    const header = parseHeader(ts);
    if (header.displayName && !displayName) displayName = header.displayName;
    if (header.description && !description) description = header.description;
    if (header.version && version === null) version = Number(header.version);
    for (const c of parseCredentials(ts)) credentials.add(c);

    const body = extractParamsTypeBody(ts);
    if (!body) continue;

    const disc = parseDiscriminators(ts);
    operations.push({
      resource: disc.resource ?? resource ?? null,
      operation: disc.operation ?? null,
      mode: disc.mode ?? null,
      params: parseTopLevelParams(body).map((p) => (p.required ? `${p.name}!` : p.name)),
      grounded: parseGroundedParams(ts),
      // path relative to the schemas root, so get_node_schema can find the file
      file: path.relative(versionDir, file).split(path.sep).join('/'),
    });
  }

  if (!operations.length) return null;

  return {
    type: nodeType,
    name: nodeName,
    displayName: displayName || nodeName,
    description: description || null,
    version,
    versionDir: versionDirName,
    pkg: pkgName,
    credentials: [...credentials],
    operations,
  };
}

// ---------------------------------------------------------------------------
// main

function main() {
  const started = Date.now();
  const packages = {};
  /** @type {any[]} */
  const nodes = [];

  rmrf(OUT);
  fs.mkdirSync(OUT, { recursive: true });

  for (const pkg of PACKAGES) {
    const pkgRoot = path.join(SRC, pkg.npm);
    const pkgJson = readJson(path.join(pkgRoot, 'package.json'));
    if (!pkgJson) {
      console.error(`  ! ${pkg.npm} not installed under ${SRC} — skipping`);
      continue;
    }
    packages[pkg.npm] = pkgJson.version;

    const defsRoot = path.join(pkgRoot, pkg.defs);
    if (!exists(defsRoot)) {
      console.error(`  ! ${pkg.npm}@${pkgJson.version} has no node-definitions tree — skipping`);
      continue;
    }

    for (const pkgDirName of fs.readdirSync(defsRoot)) {
      const pkgDir = path.join(defsRoot, pkgDirName);
      if (!fs.statSync(pkgDir).isDirectory()) continue;

      for (const nodeName of fs.readdirSync(pkgDir)) {
        const nodeDir = path.join(pkgDir, nodeName);
        if (!fs.statSync(nodeDir).isDirectory()) continue;

        let entry = null;
        try {
          entry = buildNode({ pkgName: pkgDirName, nodeDir, nodeName });
        } catch (err) {
          console.error(`  ! ${pkgDirName}.${nodeName}: ${err.message}`);
          continue;
        }
        if (!entry) continue;
        nodes.push(entry);

        if (!CATALOG_ONLY) {
          const srcVersionDir = entry.versionDir ? path.join(nodeDir, entry.versionDir) : nodeDir;
          // The `nodes/` segment is required: @n8n/workflow-sdk resolves
          // schemas at <baseDir>/nodes/<pkg>/<node>/. Emitting them one level
          // up makes every lookup return null, and a null schema is treated as
          // "nothing to check" — so validation passes everything and reports
          // itself healthy. Verified against tryLoadSchemaForNodeType().
          const destDir = path.join(OUT, 'schemas', 'nodes', pkgDirName, nodeName, entry.versionDir || 'v1');
          copyTree(srcVersionDir, destDir);
        }
      }
    }
  }

  nodes.sort((a, b) => a.type.localeCompare(b.type));

  const catalog = {
    // Stamped so the assistant can say "my index is for n8n-nodes-base 2.15.1"
    // and refuse to claim certainty when the live instance reports something else.
    generatedAt: new Date().toISOString(),
    packages,
    nodeCount: nodes.length,
    operationCount: nodes.reduce((n, x) => n + x.operations.length, 0),
    nodes,
  };

  // n8n's schema files are CommonJS, but this app is "type": "module", which
  // makes Node treat every .js under it as ESM and refuse to require() them.
  // The SDK swallows that failure and returns null, and a null schema counts as
  // "nothing to validate" — so validation passes everything while looking
  // healthy. This marker scopes the vendored tree back to CommonJS.
  if (!CATALOG_ONLY) {
    fs.mkdirSync(path.join(OUT, 'schemas'), { recursive: true });
    fs.writeFileSync(path.join(OUT, 'schemas', 'package.json'), JSON.stringify({ type: 'commonjs' }, null, 2));
  }

  fs.writeFileSync(path.join(OUT, 'catalog.json'), JSON.stringify(catalog));
  fs.writeFileSync(
    path.join(OUT, 'catalog.meta.json'),
    JSON.stringify({ generatedAt: catalog.generatedAt, packages, nodeCount: catalog.nodeCount, operationCount: catalog.operationCount }, null, 2),
  );

  const size = (p) => {
    let total = 0;
    const walk = (d) => {
      for (const e of fs.readdirSync(d, { withFileTypes: true })) {
        const q = path.join(d, e.name);
        if (e.isDirectory()) walk(q);
        else total += fs.statSync(q).size;
      }
    };
    if (exists(p)) walk(p);
    return total;
  };

  console.log(`nodes:      ${catalog.nodeCount}`);
  console.log(`operations: ${catalog.operationCount}`);
  console.log(`packages:   ${JSON.stringify(packages)}`);
  console.log(`catalog:    ${(fs.statSync(path.join(OUT, 'catalog.json')).size / 1e6).toFixed(2)} MB`);
  if (!CATALOG_ONLY) console.log(`schemas:    ${(size(path.join(OUT, 'schemas')) / 1e6).toFixed(2)} MB`);
  console.log(`took:       ${((Date.now() - started) / 1000).toFixed(1)}s`);
}

function copyTree(from, to) {
  for (const e of fs.readdirSync(from, { withFileTypes: true })) {
    const src = path.join(from, e.name);
    const dst = path.join(to, e.name);
    if (e.isDirectory()) copyTree(src, dst);
    else if (e.name.endsWith('.ts') || e.name.endsWith('.schema.js')) copyFileEnsuring(src, dst);
  }
}

main();
